cat >> src/boxOffice.test.ts <<'EOF'

import { createBoxOffice, type BoxOfficeOptions } from "./boxOffice";

function setup(overrides: Partial<BoxOfficeOptions> = {}) {
  const clock = { time: 1_000_000 };
  const office = createBoxOffice({
    sections: [
      { id: "PARKETT", capacity: 10, priceCents: 5000 },
      { id: "BALKON", capacity: 5, priceCents: 3000 },
    ],
    holdMinutes: 15,
    maxTicketsPerCustomer: 6,
    now: () => clock.time,
    ...overrides,
  });
  return { office, clock };
}

function expectCode(fn: () => unknown, code: string) {
  let caught: unknown;
  try {
    fn();
  } catch (e) {
    caught = e;
  }
  expect(caught).toBeInstanceOf(BoxOfficeError);
  expect((caught as BoxOfficeError).code).toBe(code);
}

describe("available", () => {
  test("fresh section returns its capacity", () => {
    const { office } = setup();
    expect(office.available("PARKETT")).toBe(10);
    expect(office.available("BALKON")).toBe(5);
  });
});
EOF
bun test 2>&1 | tail -5

